corefile:
.:53 {
    errors
    health {
        lameduck 5s
      }
    ready
    kubernetes cluster.local in-addr.arpa ip6.arpa {
      pods insecure
      fallthrough in-addr.arpa ip6.arpa
    }
    prometheus :9153
    forward . /etc/resolv.conf
    cache 30
    loop
    reload
    loadbalance
}
az.cloudbridge.internal:53 privatelink.blob.core.windows.net:53 blob.core.windows.net:53 {
    errors
    cache 30
    forward . 10.10.240.40 10.10.240.56 {
      policy sequential
      health_check 5s
    }
    reload
}
